//! Connection-scoped shield display data. Numeric registry ids are never builtin ordering.
use azalea_inventory::{ItemStackData,components};
use azalea_registry::{Holder,DataRegistry};
use super::ItemSnapshot;
#[derive(Debug,Clone,PartialEq,serde::Serialize,serde::Deserialize)]
pub struct Layer {pub registry_id:Option<u32>,pub asset_id:Option<String>,pub color:i32}
#[derive(Debug,Clone,PartialEq,serde::Serialize,serde::Deserialize)]
pub struct Shield {pub patterned:bool,pub base_color:Option<u8>,pub layers:Vec<Layer>,pub complete:bool}
fn identifier(s:&str)->bool{let Some((namespace,path))=s.split_once(':')else{return false;};!namespace.is_empty()&&!path.is_empty()&&s.len()<=256&&!path.contains("..")&&namespace.bytes().all(|c|c.is_ascii_lowercase()||c.is_ascii_digit()||b"_.-".contains(&c))&&path.bytes().all(|c|c.is_ascii_lowercase()||c.is_ascii_digit()||b"/_.-".contains(&c))}
pub fn snapshot(item:&ItemStackData)->Option<Shield>{if item.kind!=azalea_registry::builtin::ItemKind::Shield{return None;}
 let base_color=item.get_component::<components::BaseColor>().map(|v|v.color as u8);
 let patterns=item.get_component::<components::BannerPatterns>();let patterned=base_color.is_some()||patterns.as_ref().is_some_and(|v|!v.patterns.is_empty());
 let layers=patterns.map(|p|p.patterns.iter().take(16).map(|p|{let(registry_id,asset_id)=match &p.pattern{Holder::Reference(id)=>(Some(id.protocol_id()),None),Holder::Direct(v)=>(None,identifier(&v.asset_id.to_string()).then(||v.asset_id.to_string()))};Layer{registry_id,asset_id,color:p.color}}).collect()).unwrap_or_default();
 Some(Shield{patterned,base_color,layers,complete:true})
}
#[derive(Default)]pub struct Registry {assets:Vec<Option<String>>}
impl Registry {
 pub fn clear(&mut self){self.assets.clear();}
 pub fn ingest(&mut self,packet:&azalea_protocol::packets::config::ClientboundRegistryData){if packet.registry_id.to_string()!="minecraft:banner_pattern"{return;}self.clear();if packet.entries.len()>4096{return;}
  let official:std::collections::BTreeMap<String,String>=serde_json::from_str(include_str!("native_java_shield_patterns.json")).expect("verified official pattern identities");
  self.assets=packet.entries.iter().map(|(key,data)|{let asset=match data{Some(nbt)=>nbt.string("asset_id").map(|s|s.to_string()),None=>official.get(&key.to_string()).cloned()};asset.filter(|s|identifier(s))}).collect();
 }
 fn resolve_shield(&self,shield:&mut Shield){shield.complete=true;for layer in &mut shield.layers{if let Some(id)=layer.registry_id{layer.asset_id=self.assets.get(id as usize).cloned().flatten();}if layer.asset_id.as_ref().is_none_or(|id|!identifier(id))||!(0..16).contains(&layer.color){shield.complete=false;}}}
 fn item(&self,item:&mut Option<ItemSnapshot>){if let Some(item)=item{if let Some(shield)=&mut item.shield{self.resolve_shield(shield);}}}
 pub fn inventory(&self,inventory:&mut super::super::native_java::InventorySnapshot){self.item(&mut inventory.carried_item);self.item(&mut inventory.held);self.item(&mut inventory.offhand);for item in inventory.items.iter_mut().chain(inventory.hotbar.iter_mut()).chain(inventory.armor.iter_mut()){self.item(item);}}
 pub fn entities(&self,entities:&mut [super::super::native_java::EntitySnapshot]){for entity in entities{self.item(&mut entity.dropped_item);for item in &mut entity.equipment{self.item(item);}if let Some(value)=entity.display.get_mut("item").and_then(|i|i.get_mut("shield")){if let Ok(mut shield)=serde_json::from_value::<Shield>(value.clone()){self.resolve_shield(&mut shield);*value=serde_json::to_value(shield).expect("shield JSON");}}}}
 pub fn recipes(&self,mut recipes:super::super::native_java::recipes::RecipeSnapshot)->super::super::native_java::recipes::RecipeSnapshot{for recipe in &mut recipes.entries{if let Some(shield)=&mut recipe.result.shield{self.resolve_shield(shield);}for item in &mut recipe.ingredients{self.item(item);}}if let Some(ghost)=&mut recipes.ghost{if let Some(shield)=&mut ghost.result.shield{self.resolve_shield(shield);}for item in &mut ghost.ingredients{self.item(item);}}recipes}
}
#[cfg(test)]mod tests {
 use super::*;use azalea_inventory::ItemStack;use azalea_registry::{builtin::ItemKind,data};use azalea_protocol::packets::config::ClientboundRegistryData;
 fn shield(id:u32)->Option<ItemSnapshot>{super::super::snapshot(&ItemStack::new(ItemKind::Shield,1).with_component(components::BannerPatterns{patterns:vec![components::BannerPattern{pattern:Holder::Reference(data::BannerPattern::new_raw(id)),color:14}]}))}
 fn registry(keys:&[&str])->ClientboundRegistryData{ClientboundRegistryData{registry_id:"minecraft:banner_pattern".parse().unwrap(),entries:keys.iter().map(|key|(key.parse().unwrap(),None)).collect()}}
 #[test]fn packet_registry_order_holes_replacement_and_clear_are_connection_scoped(){let mut registry_state=Registry::default();registry_state.ingest(&registry(&["minecraft:flow","custom:missing","minecraft:base"]));let mut first=shield(0);registry_state.item(&mut first);assert_eq!(first.as_ref().unwrap().shield.as_ref().unwrap().layers[0].asset_id.as_deref(),Some("minecraft:flow"));let mut missing=shield(1);registry_state.item(&mut missing);assert!(!missing.unwrap().shield.unwrap().complete);let mut last=shield(2);registry_state.item(&mut last);assert_eq!(last.unwrap().shield.unwrap().layers[0].asset_id.as_deref(),Some("minecraft:base"));registry_state.clear();registry_state.item(&mut first);assert!(!first.as_ref().unwrap().shield.as_ref().unwrap().complete);registry_state.ingest(&registry(&["minecraft:guster"]));registry_state.item(&mut first);assert_eq!(first.unwrap().shield.unwrap().layers[0].asset_id.as_deref(),Some("minecraft:guster"));}
 #[test]fn explicit_registry_asset_and_inline_asset_use_their_actual_identity(){let mut packet=registry(&["minecraft:base"]);packet.entries[0].1=Some(Default::default());packet.entries[0].1.as_mut().unwrap().insert("asset_id","minecraft:creeper");let mut r=Registry::default();r.ingest(&packet);let mut item=shield(0);r.item(&mut item);assert_eq!(item.unwrap().shield.unwrap().layers[0].asset_id.as_deref(),Some("minecraft:creeper"));packet.entries[0].1=Some(Default::default());r.ingest(&packet);let mut item=shield(0);r.item(&mut item);assert!(!item.unwrap().shield.unwrap().complete,"malformed explicit entry is not guessed from builtin name");let stack=ItemStack::new(ItemKind::Shield,1).with_component(components::BannerPatterns{patterns:vec![components::BannerPattern{pattern:Holder::Direct(components::BannerPatternData{asset_id:"custom:real_texture".parse().unwrap(),translation_key:"custom.key".into()}),color:4}]});let mut item=super::super::snapshot(&stack);r.clear();r.item(&mut item);let shield=item.unwrap().shield.unwrap();assert!(shield.complete);assert_eq!(shield.layers[0].asset_id.as_deref(),Some("custom:real_texture"));}
 #[test]fn actual_components_distinguish_base_color_from_generic_dye_and_bound_rendered_layers(){let plain=super::super::snapshot(&ItemStack::new(ItemKind::Shield,1)).unwrap().shield.unwrap();assert!(!plain.patterned&&plain.base_color.is_none());let dye=super::super::snapshot(&ItemStack::new(ItemKind::Shield,1).with_component(components::DyedColor{rgb:0xff0000})).unwrap();assert_eq!(dye.dyed_color,Some(0xff0000));assert!(!dye.shield.unwrap().patterned);let mut stack=ItemStack::new(ItemKind::Shield,1).with_component(components::BaseColor{color:components::DyeColor::Blue});let layer=components::BannerPattern{pattern:Holder::Direct(components::BannerPatternData{asset_id:"minecraft:flow".parse().unwrap(),translation_key:"x".into()}),color:14};stack=stack.with_component(components::BannerPatterns{patterns:vec![layer;20]});let out=super::super::snapshot(&stack).unwrap().shield.unwrap();assert!(out.patterned);assert_eq!(out.base_color,Some(11));assert_eq!(out.layers.len(),16);}
}
